#!/usr/bin/python3 -B
"""One-shot unexecuted carried-suite suffix; not a retry or whole-suite pass.

All test assertions in the suffix are byte-exact original source. Setup records
are separate; named-FIFO creation and the first 73 observations are not retried.
Run only on a fresh copy of the frozen image after review of the companion plan.
"""
import base64, hashlib, json, pathlib, sys
MANIFEST = {'original_source': 'B2/build/round2-selftest.py', 'original_sha256': '70097e1e9ab373d95f081acb0b0d835575a3b9b5c64498397e933800a9bbb119', 'probe_source': 'B2/build/round2-probe.c', 'probe_sha256': 'c5dbf0731413097ab45af227b6c89ba78de8a4389842430f597dc08f30402f83', 'original_prefix_lines': [1, 43], 'setup_lines': [[45, 45], [49, 110]], 'hostile_mapping_line': 175, 'unchanged_suffix_lines': [178, 331], 'unchanged_suffix_sha256': '9ace38b00baeb15a7b959440217e801eb4fb5a6d148ca9ab5218d4ae9a37d5fe', 'setup_ids': ['FIXTURE-COMPILE', 'FIXTURE-LIBRARY', 'FIXTURE-HOLDER', 'ADMIT'], 'expected_result_ids': ['SEALED-SOCKET', 'REPL-PTY', 'ENVIRONMENT', 'PRELOAD', 'SHELL-STARTUP', 'TYPED', 'FUNCTION', 'ALIAS', 'SUBSTITUTION', 'PROCESS-SUBSTITUTION', 'HEREDOC', 'LOADER', 'NATIVE-KERNEL', 'EDITOR-POSITIVE', 'EDITOR-READ', 'EDITOR-CONTENT', 'EDITOR-ESCAPE', 'EDITOR-GLOBAL', 'EDITOR-SOURCE', 'EDITOR-DEFINITION', 'EDITOR-MODELINE', 'EDITOR-MODELINE-CONTENT', 'WRITER-OPERAND', 'WRITER-EXTRA-OPTION', 'WRITER-NO-TARGET', 'BROWSER', 'BROWSER-OPTIONS', 'BROWSER-EXTENSION-REQUEST', 'HOME-PREFERENCE-ONE', 'HOME-PREFERENCE-TWO', 'NATIVE-downloaded', 'NATIVE-nested-extracted.renamed', 'NATIVE-build-output', 'NATIVE-prefix-bin-app', 'NATIVE-old-copy', 'NATIVE-SYMLINK', 'OVERWRITE', 'LOGIN-KEY-CP', 'LOGIN-KEY-WRITER', 'LOGIN-KEY-ED', 'LOGIN-KEY-UNCHANGED', 'SERVICE-PROGRAM-ADMIT', 'SERVICE-ADMISSION-PIPE-ARG', 'SERVICE-ADMISSION-RESTART', 'SERVICE-LIFECYCLE-ADMIT', 'TIMER-LIFECYCLE-ADMIT', 'SERVICE-TIMER-UPDATE', 'SERVICE-TIMER-CODE-CHANGE', 'TIMER-LIFECYCLE-REMOVE', 'SERVICE-LIFECYCLE-REMOVE', 'SERVICE-LIFECYCLE-REMOVED', 'SERVICE-PROGRAM-REMOVE', 'REMOVE', 'REMOVE-HOLDER', 'REMOVE-PROFILES', 'REMOVED-SCRIPT', 'REMOVED-NATIVE', 'REMOVED-COPY', 'VERIFY'], 'expected_boolean_results': 59, 'not_tested': [{'id': 'SEALED-FIFO', 'reason': 'original FIFO setup failed with EROFS; no retry'}], 'original_first_73_repeated': False, 'whole_original_suite_remains_incomplete': True, 'execution_status': 'not executed'}
SOURCE_B64 = ''
PROBE_B64 = ''

def main():
    source=base64.b64decode(SOURCE_B64)
    probe=base64.b64decode(PROBE_B64)
    assert hashlib.sha256(source).hexdigest()==MANIFEST['original_sha256']
    assert hashlib.sha256(probe).hexdigest()==MANIFEST['probe_sha256']
    lines=source.decode().splitlines(keepends=True)
    suffix=''.join(lines[177:-1])
    assert hashlib.sha256(suffix.encode()).hexdigest()==MANIFEST['unchanged_suffix_sha256']
    # A second invocation on the same guest fails before fixture construction.
    directory=pathlib.Path('/var/lib/stand/bc3-round2-continuation')
    directory.mkdir(mode=0o700)
    original=directory/'round2-selftest.py'
    original.write_bytes(source)
    (directory/'round2-probe.c').write_bytes(probe)
    (directory/'provenance.json').write_text(json.dumps(MANIFEST,sort_keys=True,indent=2)+'\n')
    sys.argv=[str(original),str(directory/'observations.jsonl')]
    scope={'__file__':str(original),'__name__':'bc3_continuation_original'}
    exec(compile(''.join(lines[:43]),str(original), 'exec'),scope)
    original_record=scope['record']
    stage={'name':'setup'}
    seen=[]
    setup_results=[]
    def record(row):
        row=dict(row)
        row['continuation_scope']=stage['name']
        if stage['name']=='setup':
            row['original_phase']=row.get('phase')
            row['phase']='setup_'+row.get('phase','event')
            if 'passed' in row:
                row['setup_passed']=row.pop('passed')
                setup_results.append((row.get('id'),row['setup_passed']))
        elif row.get('phase')!='summary' and type(row.get('passed')) is bool:
            seen.append(row['id'])
        if row.get('phase')=='summary':
            row['whole_original_suite_complete']=False
            row['unavailable_ids']=['SEALED-FIFO']
        original_record(row)
    scope['record']=record
    def begin_suffix():
        if setup_results!=[(x,True) for x in MANIFEST['setup_ids']] or scope['failed']:
            raise RuntimeError('continuation setup incomplete or failed')
        stage['name']='suffix'
        record({'phase':'not-tested','status':'NOT-TESTED','id':'SEALED-FIFO',
                'reason':'original FIFO setup failed with EROFS; no retry; no pass claimed'})
    scope['begin_suffix']=begin_suffix
    setup=lines[44]+''.join(lines[48:110])
    body='def main():\n'+setup+lines[174]+' begin_suffix()\n'+suffix
    exec(compile(body,str(original)+':continuation','exec'),scope)
    original_record({'phase':'continuation_plan','provenance':MANIFEST})
    status=scope['main']()
    inventory_ok=seen==MANIFEST['expected_result_ids']
    original_record({'phase':'continuation_completion','expected_results':59,
        'observed_results':len(seen),'observed_ids':seen,'result_inventory_complete':inventory_ok,
        'suffix_exit':int(status),'whole_original_suite_complete':False,
        'not_tested':['SEALED-FIFO'],'hypothesis_outcome':'?'})
    if not inventory_ok:
        raise RuntimeError('continuation result inventory differs from fixed plan')
    return int(status)

if __name__=='__main__':
    raise SystemExit(main())
